import sys
from pathlib import Path
from uuid import uuid4

ROOT = Path.cwd()
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from tools.intake_tools import intake_step, intake_snapshot, intake_finalize, reset_session

_SESSION = {"id": None}


def _ensure_session():
    if _SESSION["id"] is None:
        _SESSION["id"] = str(uuid4())
    return _SESSION["id"]


def intake_step_tool(user_text: str):
    session_id = _ensure_session()
    return intake_step(session_id=session_id, user_text=user_text)


def intake_snapshot_tool():
    session_id = _ensure_session()
    return intake_snapshot(session_id=session_id)


def intake_finalize_tool():
    session_id = _ensure_session()
    payload = intake_finalize(session_id=session_id)
    _SESSION["id"] = None
    return payload


def intake_reset_tool():
    if _SESSION["id"] is not None:
        reset_session(_SESSION["id"])
    _SESSION["id"] = None
    return {"status": "reset"}

import sys
from pathlib import Path

ROOT = Path.cwd()
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from tools.cocomo_tools import generate_cocomo_ii_estimation
from tools.storypoints_tools import generate_storypoints_estimation
from tools.parametric_tools import generate_parametric_estimation

_ESTIMATORS = {
    "cocomo": generate_cocomo_ii_estimation,
    "storypoints": generate_storypoints_estimation,
    "parametric": generate_parametric_estimation,
}

def run_estimation_tool(payload: dict):
    method = payload.get("method")
    kwargs = payload.get("kwargs", {})
    if method not in _ESTIMATORS:
        raise ValueError(f"Unsupported estimation method '{method}'.")
    result = _ESTIMATORS[method](**kwargs)
    return result.model_dump_json(indent=2)
